@import '../../utils/control-parts.css';
@import '../../utils/forced-colors.css';

:host {
  display: inline-flex;
  align-items: center;
  box-sizing: border-box;
  min-width: 0;
  --_score-badge-inline-size: var(--dimension-size-500);
  --_score-badge-block-size: var(--dimension-size-400);
  /* Matches the text skeleton’s 75% bar so the fill inset is even on all sides. */
  --_score-skeleton-inset: calc(var(--_score-badge-block-size) / 8);
}

:host(.score--sm) {
  --_score-badge-inline-size: calc(var(--dimension-size-400) - var(--dimension-space-050));
  --_score-badge-block-size: var(--dimension-size-300);
}

:host(.score--md) {
  --_score-badge-inline-size: var(--dimension-size-500);
  --_score-badge-block-size: var(--dimension-size-400);
}

:host(.score--lg) {
  --_score-badge-inline-size: calc(var(--dimension-size-600) + var(--dimension-space-100));
  --_score-badge-block-size: var(--dimension-size-500);
}

.score__badge {
  display: flex;
  flex: 0 0 auto;
  align-items: center;
  justify-content: center;
  box-sizing: border-box;
  inline-size: var(--_score-badge-inline-size);
  block-size: var(--_score-badge-block-size);
  overflow: hidden;
  border-radius: var(--dimension-radius-025);
  background: var(--color-background-faint-neutral);
  color: var(--color-foreground-bold-neutral);
  -webkit-user-select: none;
  user-select: none;
}

.score__badge--fair {
  background: var(--color-safety-score-background-fair);
  color: var(--color-safety-score-foreground-on-fair);
}

.score__badge--good {
  background: var(--color-safety-score-background-good);
  color: var(--color-safety-score-foreground-on-good);
}

.score__badge--excellent {
  background: var(--color-safety-score-background-excellent);
  color: var(--color-safety-score-foreground-on-excellent);
}

.score__value,
.score__badge ds-skeleton {
  flex: 0 0 auto;
}

.score__badge--loading {
  padding-inline: var(--_score-skeleton-inset);
}

.score__badge--loading .score__value {
  flex: 1 1 auto;
  inline-size: 100%;
  block-size: 100%;
  max-inline-size: 100%;
  max-block-size: 100%;
  min-inline-size: 0;
}

@media (forced-colors: active) {
  .score__badge {
    border: var(--dimension-stroke-width-012) solid var(--ds-forced-color-content);
    background: var(--ds-forced-color-surface);
    color: var(--ds-forced-color-content);
  }
}

import { Component, Prop, h, Host } from '@stencil/core';
import { SCORE_VALUE_VARIANT, resolveScoreLevel } from './score-model';
import type { SafetyScoreLevel, ScoreSize, ScoreVariant } from './score-types';

@Component({
  tag: 'ds-score',
  styleUrl: 'Score.css',
  scoped: true,
})
export class Score {
  /** Display-ready headline figure. */
  @Prop() value: string | number = '';
  /**
   * Visual density matching control height: `sm` 24px, `md` 32px, `lg` 40px.
   * `lg` is the Card Overview recipe.
   */
  @Prop() size: ScoreSize = 'md';
  /**
   * Value typography recipe. `dense` keeps the selected size's fill dimensions
   * and uses a larger emphasized figure with tighter surrounding space.
   */
  @Prop() variant: ScoreVariant = 'default';
  /**
   * Safety-score color level. Numeric values from 0–100 infer fair (0–50),
   * good (51–80), or excellent (81–100) when this is omitted.
   */
  @Prop() level: SafetyScoreLevel | undefined;
  /** Replace the figure with a skeleton while data resolves. */
  @Prop() isLoading: boolean = false;
  /** Accessible name prefix, for example “Safety score”. */
  @Prop() label: string = '';

  render() {
    const size = this.size;
    const variant = this.variant;
    const level = resolveScoreLevel(this.value, this.level);
    const valueVariant = SCORE_VALUE_VARIANT[variant][size];
    const accessibleName = [this.label.trim(), this.isLoading ? '' : this.value]
      .filter(Boolean)
      .join(' ');

    return (
      <Host
        class={{
          score: true,
          [`score--${size}`]: true,
          [`score--${variant}`]: true,
          'score--loading': this.isLoading,
        }}
        role={accessibleName ? 'img' : undefined}
        aria-busy={this.isLoading ? 'true' : undefined}
        aria-label={accessibleName || undefined}
      >
        <span
          class={{
            score__badge: true,
            [`score__badge--${level}`]: Boolean(level),
            'score__badge--loading': this.isLoading,
          }}
        >
          {this.isLoading ? (
            <ds-skeleton
              class="score__value"
              variant="text"
              textVariant={valueVariant}
              background={level ? 'bold' : 'faint'}
            />
          ) : (
            <ds-text
              as="span"
              class="score__value ds-control-label-box"
              variant={valueVariant}
              emphasis={true}
              color="inherit"
              fontFeature="tabular-nums"
            >
              {this.value}
            </ds-text>
          )}
        </span>
      </Host>
    );
  }
}

import {
  SAFETY_SCORE_LEVELS,
  type SafetyScoreLevel,
  type ScoreSize,
  type ScoreVariant,
} from './score-types';

export function isSafetyScoreLevel(value: unknown): value is SafetyScoreLevel {
  return typeof value === 'string' && (SAFETY_SCORE_LEVELS as readonly string[]).includes(value);
}

/**
 * Infer a safety-score color level from a 0–100 figure. Non-numeric or out-of-range
 * values return undefined so the owner can supply `level` explicitly.
 */
export function resolveSafetyScoreLevel(value: string | number): SafetyScoreLevel | undefined {
  if (typeof value === 'string' && value.trim() === '') return undefined;
  const numericValue = typeof value === 'number' ? value : Number(value);
  if (!Number.isFinite(numericValue) || numericValue < 0 || numericValue > 100) return undefined;
  if (numericValue <= 50) return 'fair';
  if (numericValue <= 80) return 'good';
  return 'excellent';
}

export function resolveScoreLevel(
  value: string | number,
  level?: SafetyScoreLevel
): SafetyScoreLevel | undefined {
  return isSafetyScoreLevel(level) ? level : resolveSafetyScoreLevel(value);
}

export const SCORE_VALUE_VARIANT = {
  default: {
    sm: 'text-title-small',
    md: 'text-title-medium',
    lg: 'text-title-large',
  },
  dense: {
    sm: 'text-title-medium',
    md: 'text-title-large',
    lg: 'text-display-small',
  },
} as const satisfies Record<
  ScoreVariant,
  Record<
    ScoreSize,
    'text-title-small' | 'text-title-medium' | 'text-title-large' | 'text-display-small'
  >
>;

export type SafetyScoreLevel = 'fair' | 'good' | 'excellent';
export type ScoreSize = 'sm' | 'md' | 'lg';
export type ScoreVariant = 'default' | 'dense';

export const SCORE_SIZES = ['sm', 'md', 'lg'] as const;
export const SCORE_VARIANTS = ['default', 'dense'] as const;
export const SAFETY_SCORE_LEVELS = ['fair', 'good', 'excellent'] as const;
